'use strict';
// Nightly. Writes exports/agent-summary.json: for each agent, how many ratings their tickets received in the
// past seven days, and the average score. Lets team leads see this without asking.
const fs = require('node:fs');
const path = require('node:path');

const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');
const WINDOW_DAYS = 7;
const DAY = 24 * 60 * 60 * 1000;

function weeklySummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
  const totals = new Map();
  for (const rating of store.listRatings()) {
    if (now.getTime() - new Date(rating.at).getTime() >= WINDOW_DAYS * DAY) continue;
    const ticket = store.getTicket(rating.ticket_id);
    if (!ticket || !ticket.owner_id) continue;
    const entry = totals.get(ticket.owner_id) || { count: 0, sum: 0 };
    entry.count += 1;
    entry.sum += rating.score;
    totals.set(ticket.owner_id, entry);
  }
  const rows = [...totals.entries()]
    .sort(([a], [b]) => a - b)
    .map(([agentId, { count, sum }]) => ({
      agent_id: agentId,
      ratings: count,
      average: Math.round((sum / count) * 100) / 100,
    }));
  fs.mkdirSync(dir, { recursive: true });
  const file = path.join(dir, 'agent-summary.json');
  fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
  return { file, agents: rows.length };
}

module.exports = { weeklySummary, WINDOW_DAYS };
```

